import{_ as l,a0 as p,w as d,s as o,ao as r,I as n,x as s,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 命令行中转换大小写 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 命令行中转换大小写 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 命令行中转换大小写 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 命令行中转换大小写 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200228 Converting between uppercase and lowercase on the Linux command line","title":"在 Linux 命令行中转换大小写","tag":"202003","desc":""},"relativePath":"202003/20200228 Converting between uppercase and lowercase on the Linux command line.md","filePath":"[post].md"}'),h={name:"202003/20200228 Converting between uppercase and lowercase on the Linux command line.md"};function c(g,e,k,u,b,m){const a=p("Link");return d(),o("div",null,[e[15]||(e[15]=r(`<h1 id="在-linux-命令行中转换大小写" tabindex="-1">在 Linux 命令行中转换大小写 <a class="header-anchor" href="#在-linux-命令行中转换大小写" aria-label="Permalink to “在 Linux 命令行中转换大小写”">​</a></h1><blockquote><p>转换文本的大小写可能非常繁琐，尤其是当你要避免无意间的拼写错误时。幸运的是，Linux 提供了一些命令，可以使工作变得非常容易。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/11/095821df7u8nlyfyyydqvf.jpg" alt=""></p><p>有很多方法可以在 Linux 命令行中将文本从小写更改为大写，反之亦然。实际上，有一组这样的命令可以选择。这篇文章检验了一些最佳的命令来完成这项工作，以及你该如何让它们正常工作。</p><h3 id="使用-tr" tabindex="-1">使用 tr <a class="header-anchor" href="#使用-tr" aria-label="Permalink to “使用 tr”">​</a></h3><p><code>tr</code>（translate）命令是在命令行或脚本中最容易使用的命令之一。如果你要确定要一串大写字符串，你只需将它传给 <code>tr</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo Hello There | tr [:lower:] [:upper:]</span></span>
<span class="line"><span>HELLO THERE</span></span></code></pre></div><p>下面是一个在脚本中使用这个命令的例子，当你要确保添加到文件中的所有文本都使用大写形式以保持一致性时（LCTT 译注：这里输入部门名称作为示例）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo -n &quot;Enter department name: &quot;</span></span>
<span class="line"><span>read dept</span></span>
<span class="line"><span>echo $dept | tr [:lower:] [:upper:] &gt;&gt; depts</span></span></code></pre></div><p>将顺序切换为 <code>[:upper:] [:lower:]</code> 会产生相反的效果，将所有大写的部门名称都转换为小写：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | tr [:upper:] [:lower:] &gt;&gt; depts</span></span></code></pre></div><p>同样，你可以使用 <code>sed</code> 命令的 <code>A-Z</code> 和 <code>a-z</code> 字符串完成相同的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | tr a-z A-Z &gt;&gt; depts</span></span></code></pre></div><p>毫无疑问，反转 <code>a-z</code> 和 <code>A-Z</code> 字符串的顺序将产生相反的效果，将文本全部变为小写。</p><h3 id="使用-awk" tabindex="-1">使用 awk <a class="header-anchor" href="#使用-awk" aria-label="Permalink to “使用 awk”">​</a></h3><p><code>awk</code> 命令可让你使用它的 <code>toupper</code> 和 <code>tolower</code> 选项执行相同的操作。上例脚本中的命令可以用这种方式代替：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | awk &#39;{print toupper($0)}&#39; &gt;&gt; depts</span></span></code></pre></div><p>相反操作（切换为小写）如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | awk &#39;{print tolower($0)}&#39; &gt;&gt; depts</span></span></code></pre></div><h3 id="使用-sed" tabindex="-1">使用 sed <a class="header-anchor" href="#使用-sed" aria-label="Permalink to “使用 sed”">​</a></h3><p><code>sed</code>（stream editor）命令也可用于切换大小写。它与上面显示的两个命令中的第一个具有相同的效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | sed &#39;s/[a-z]/\\U&amp;/g&#39; &gt;&gt; depts</span></span></code></pre></div><p>从大写字母切换到小写字母只需将行尾附近的 <code>U</code> 替换为 <code>L</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | sed &#39;s/[A-Z]/\\L&amp;/g&#39; &gt;&gt; depts</span></span></code></pre></div><h3 id="操作文件中的文本" tabindex="-1">操作文件中的文本 <a class="header-anchor" href="#操作文件中的文本" aria-label="Permalink to “操作文件中的文本”">​</a></h3><p><code>awk</code> 和 <code>sed</code> 都能更改整个文件的文本大小写。因此，你发现你的老板需要所有部门名称的小写么？没问题。只需带上文件名运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;{print tolower($0)}&#39; depts</span></span>
<span class="line"><span>finance</span></span>
<span class="line"><span>billing</span></span>
<span class="line"><span>bookkeeping</span></span></code></pre></div><p>如果要覆盖 <code>depts</code> 文件，而不仅仅是以小写形式显示，则需要执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;{print tolower($0)}&#39; depts &gt; depts-</span></span>
<span class="line"><span>$ mv depts- depts</span></span></code></pre></div><p>但是，使用 <code>sed</code> 进行更改，你可以避免最后一步，因为 <code>sed</code> 可以“原地”编辑文件，如下所示，文件完整，但文本全部小写：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed &#39;s/[A-Z]/\\L&amp;/g&#39; depts</span></span></code></pre></div><h3 id="仅将首字母转换为大写" tabindex="-1">仅将首字母转换为大写 <a class="header-anchor" href="#仅将首字母转换为大写" aria-label="Permalink to “仅将首字母转换为大写”">​</a></h3><p>要仅将字符串中单词的首字母转换为大写，那么可以执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo design \\&amp; engineering| sed -e &quot;s/\\b\\(.\\)/\\u\\1/g&quot;</span></span>
<span class="line"><span>Design &amp; Engineering</span></span></code></pre></div><p>该命令将确保首字母大写，但不会更改其余字母。</p><h3 id="确保只有首字母大写" tabindex="-1">确保只有首字母大写 <a class="header-anchor" href="#确保只有首字母大写" aria-label="Permalink to “确保只有首字母大写”">​</a></h3><p>当要更改文本以使只有首字母大写时，这更具挑战性。假设你正在处理一个工作人员姓名列表，并且希望以正常的“名 姓”方式对其格式化。</p><h4 id="使用-sed-1" tabindex="-1">使用 sed <a class="header-anchor" href="#使用-sed-1" aria-label="Permalink to “使用 sed”">​</a></h4><p>你可以使用更复杂的 <code>sed</code> 命令来确保以下结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo design \\&amp; ENGINEERING | sed &#39;s/\\b\\([[:alpha:]]\\)\\([[:alpha:]]*\\)\\b/\\u\\1\\L\\2/g&#39;</span></span>
<span class="line"><span>Design &amp; Engineering</span></span></code></pre></div><h4 id="使用-python" tabindex="-1">使用 Python <a class="header-anchor" href="#使用-python" aria-label="Permalink to “使用 Python”">​</a></h4><p>如果你已安装 Python，你可以运行这样的命令，它还可以设置文本格式，以便每个单词只有首字母大写，并且它可能比上面显示的 <code>sed</code> 命令更易于解析：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo -n &quot;design &amp; engineering&quot; | python3 -c &quot;import sys; print(sys.stdin.read().title())&quot;</span></span>
<span class="line"><span>Design &amp; Engineering</span></span></code></pre></div><p>有多种方法可以在大小写之间更改文本格式。哪种方法效果最好取决于你要处理的是单个字符串还是整个文件，以及想要的最终结果。</p><hr>`,45)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://www.networkworld.com/article/3529409/converting-between-uppercase-and-lowercase-on-the-linux-command-line.html"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3529409/converting-between-uppercase-and-lowercase-on-the-linux-command-line.html",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),i(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:t(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const w=l(h,[["render",c]]);export{x as __pageData,w as default};
